formulas.expression:
IF( {!fm_DuetoProducing} = null || {!fm_DuetoProducing} = 0
  ,  IF( {!fm_DuetoNoteIssuer} = null || {!fm_DuetoNoteIssuer} = 0
    ,  IF( {!fm_DuetoUnderwriter} = null || {!fm_DuetoUnderwriter} = 0
      ,  IF( {!fm_DuetoPlacingTogether} = null || {!fm_DuetoPlacingTogether} = 0
        ,  {!fm_DuetoSeperateCoBroker}
        ,  {!fm_DuetoPlacingTogether}
        )
      ,  {!fm_DuetoUnderwriter}
      )
    ,  {!fm_DuetoNoteIssuer}
    )
  ,  {!fm_DuetoProducing}
  )

IF( {!v_LayerCount} = {!v_QSCount} , "LOL: as per slip",
  IF( {!v_QSCount} = 0 , "LOL : " & TEXT( {!Loop_Settlement_Line_Item_Debit.RefPanel__r.Currency__c} ) & " " & {!fm_MaxLOL_Unit} & " xs " & {!fm_MinLOL_Unit} ,
    "LOL : " & TEXT( {!Loop_Settlement_Line_Item_Debit.RefPanel__r.Currency__c} ) & " " & {!fm_MaxLOL_Unit} & " xs " & {!fm_MinLOL_Unit} & " and as per slip" 
  )
)
